package dev.trentdb.storage;import dev.trentdb.storage.format.*;import java.util.*;public final class DuckDbPrimitiveColumnMetadataReader{private final SingleFileBlockManager m;private final MetaBlockPointer root;private final DuckDbTableCreateInfo.ScalarLogicalType type;public DuckDbPrimitiveColumnMetadataReader(SingleFileBlockManager m,DuckDbTableEntryEnvelope.MetaPointer p,DuckDbTableCreateInfo.ScalarLogicalType t){this.m=m;this.type=t;if(t!=DuckDbTableCreateInfo.ScalarLogicalType.BOOLEAN&&t!=DuckDbTableCreateInfo.ScalarLogicalType.INTEGER&&t!=DuckDbTableCreateInfo.ScalarLogicalType.BIGINT)throw new StorageFormatException("DuckDB primitive column logical type is unsupported: "+t);if(Long.compareUnsigned(p.offset(),0xffffffffL)>0)throw new StorageFormatException("DuckDB primitive column metadata offset exceeds uint32");root=new MetaBlockPointer(p.packedBlockPointer(),(int)p.offset());if(!root.isValid())throw new StorageFormatException("DuckDB primitive column metadata pointer is invalid");}public DuckDbPrimitiveColumnMetadata read(){var r=new DuckDbBinaryMetadataReader(new MetadataChainReader(m,root),m.activeHeader().storageCompatibility());var data=column(r,type,false);return new DuckDbPrimitiveColumnMetadata(type,data[0],data[1],DuckDbPrimitiveColumnMetadata.Boundary.BLOCK_PAYLOAD_DECOMPRESSION_UNSUPPORTED);}private List[] column(DuckDbBinaryMetadataReader r,DuckDbTableCreateInfo.ScalarLogicalType t,boolean validity){r.beginObject();if(r.beginOptionalProperty(99))throw new StorageFormatException("DuckDB primitive column extra data is unsupported");List<DuckDbPrimitiveColumnMetadata.Segment> data=segments(r,t,validity);List<DuckDbPrimitiveColumnMetadata.Segment> valid=List.of();if(!validity){r.beginProperty(101);valid=column(r,t,true)[0];}r.endObject();return new List[]{data,valid};}private List<DuckDbPrimitiveColumnMetadata.Segment> segments(DuckDbBinaryMetadataReader r,DuckDbTableCreateInfo.ScalarLogicalType t,boolean validity){if(!r.beginOptionalProperty(100))return List.of();long n=r.beginList();if(Long.compareUnsigned(n,Integer.MAX_VALUE)>0)throw new StorageFormatException("DuckDB primitive segment count exceeds supported bound");var out=new ArrayList<DuckDbPrimitiveColumnMetadata.Segment>((int)n);for(long i=0;i<n;i++)out.add(segment(r,t,validity));return out;}private DuckDbPrimitiveColumnMetadata.Segment segment(DuckDbBinaryMetadataReader r,DuckDbTableCreateInfo.ScalarLogicalType t,boolean validity){r.beginObject();if(r.beginOptionalProperty(100))throw new StorageFormatException("DuckDB V2 primitive segment contains deleted row_start field 100");long count=r.beginOptionalProperty(101)?r.readUnsignedLeb128():0;r.beginProperty(102);r.beginObject();r.beginProperty(100);long block=r.readSignedLeb128();long off=r.beginOptionalProperty(101)?r.readUnsignedLeb128():0;if(block<0||block>=m.activeHeader().blockCount())throw new StorageFormatException("DuckDB primitive segment block pointer is outside committed range");if(Long.compareUnsigned(off,m.usableBlockSize())>0)throw new StorageFormatException("DuckDB primitive segment block offset exceeds usable block size");r.endObject();r.beginProperty(103);long compression=r.readUnsignedLeb128();if(compression!=1)throw new StorageFormatException("DuckDB primitive segment compression is unsupported: "+Long.toUnsignedString(compression));r.beginProperty(104);var stats=stats(r,t,validity);if(r.beginOptionalProperty(105))throw new StorageFormatException("DuckDB primitive segment state is compression-specific and unsupported");r.endObject();return new DuckDbPrimitiveColumnMetadata.Segment(count,new DuckDbPrimitiveColumnMetadata.BlockPointer(block,off),(int)compression,stats);}private DuckDbPrimitiveColumnMetadata.Statistics stats(DuckDbBinaryMetadataReader r,DuckDbTableCreateInfo.ScalarLogicalType t,boolean validity){r.beginObject();r.beginProperty(100);boolean hn=r.readBoolean();r.beginProperty(101);boolean hnn=r.readBoolean();r.beginProperty(102);long d=r.readUnsignedLeb128();r.beginProperty(103);r.beginObject();OptionalLong min=OptionalLong.empty(),max=OptionalLong.empty();if(!validity){min=bound(r,t,200);max=bound(r,t,201);}r.endObject();r.endObject();return new DuckDbPrimitiveColumnMetadata.Statistics(hn,hnn,d,min,max);}private OptionalLong bound(DuckDbBinaryMetadataReader r,DuckDbTableCreateInfo.ScalarLogicalType t,int field){if(!r.beginOptionalProperty(field))return OptionalLong.empty();r.beginObject();r.beginProperty(100);boolean present=r.readBoolean();if(!present){r.endObject();return OptionalLong.empty();}r.beginProperty(101);long v=t==DuckDbTableCreateInfo.ScalarLogicalType.BOOLEAN?(r.readBoolean()?1:0):r.readSignedLeb128();r.endObject();return OptionalLong.of(v);}}
